def compute_N(max_j, max_k):
    N = [[0] * (max_k + 1) for _ in range(max_j + 1)]
    for k in range(1, max_k + 1):
        N[0][k] = 1
    for j in range(1, max_j + 1):
        for k in range(1, max_k + 1):
            if k == 1:
                N[j][k] = 1
            else:
                N[j][k] = N[j-1][k] + N[j-1][k-1]
    return N

N = compute_N(40, 9)
print(f"N[40][9] = {N[40][9]}")
